contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint dep, uint col) public payable {
        // Constrain the collected amount to be more than the deposit but less than MinSum,
        // so that the Collect condition cannot be satisfied.
        uint minSumBefore = c.MinSum();
        require(col > dep);
        require(col < minSumBefore);
        require(dep > 0);          // a positive deposit so the balance is non-zero
        require(address(this).balance >= dep);

        c.Deposit{value: dep}();
        uint balAfterDep = c.balances(address(this));
        uint cBalAfterDep = address(c).balance;

        bool reverted;
        try c.Collect(col) { reverted = false; } catch { reverted = true; }

        // The guard `balances[msg.sender] >= _am` is false (since dep < col),
        // so the call does nothing and must not revert.
        // Hence the state must remain exactly as it was after the deposit.
        assert(!reverted && c.balances(address(this)) == balAfterDep && address(c).balance == cBalAfterDep);
    }

    receive() external payable {}
}
